import math


class Group:
    def __init__(self, members: list[str]) -> None:
        # Preserve order while ensuring uniqueness or using the given list
        self._members = list(dict.fromkeys(members))
        self._members_set = set(self._members)
        # Net balance per member in integer cents to avoid floating-point issues
        self._balances: dict[str, int] = {m: 0 for m in self._members}

    def add_expense(
        self,
        payer: str,
        amount: float,
        participants: list[str] | None = None,
    ) -> None:
        """Record that `payer` paid `amount` on behalf of `participants`."""
        if payer not in self._members_set:
            raise ValueError(f"Payer '{payer}' is not a group member.")

        if amount <= 0:
            raise ValueError("Expense amount must be positive.")

        if participants is None:
            parts = list(self._members)
        else:
            parts = list(dict.fromkeys(participants))
            if not parts:
                raise ValueError("Participants list cannot be empty.")
            for p in parts:
                if p not in self._members_set:
                    raise ValueError(f"Participant '{p}' is not a group member.")

        total_cents = round(amount * 100)
        n = len(parts)

        # Requirement 1: Each non-payer participant owes the amount rounded down to the cent.
        # Leftover cents are borne by the payer.
        base_cents = total_cents // n

        # Credit the payer for the full amount paid
        self._balances[payer] += total_cents

        if payer in parts:
            # All other participants owe base_cents.
            # The payer's own share is base_cents + leftover cents.
            for p in parts:
                if p != payer:
                    self._balances[p] -= base_cents
            payer_share = total_cents - base_cents * (n - 1)
            self._balances[payer] -= payer_share
        else:
            # Payer is not among participants: all participants owe base_cents,
            # and the leftover cents are absorbed by the payer (reducing their credit).
            for p in parts:
                self._balances[p] -= base_cents
            leftover = total_cents - base_cents * n
            self._balances[payer] -= leftover

    def balances(self) -> dict[str, float]:
        """Net balance per member. Positive = the member is owed money,
        negative = the member owes money."""
        return {m: self._balances[m] / 100.0 for m in self._members}

    def settle_up(self) -> list[tuple[str, str, float]]:
        """Payments that settle the group, as (debtor, creditor, amount)."""
        debtors: list[list] = []  # [-balance, member]
        creditors: list[list] = []  # [balance, member]

        for m in self._members:
            b = self._balances[m]
            if b < 0:
                debtors.append([-b, m])
            elif b > 0:
                creditors.append([b, m])

        # Standard greedy settlement algorithm guarantees at most (len(members) - 1) transactions.
        i = 0
        j = 0
        settlements: list[tuple[str, str, float]] = []

        while i < len(debtors) and j < len(creditors):
            debtor_owed = debtors[i][0]
            creditor_due = creditors[j][0]

            amount_to_pay = min(debtor_owed, creditor_due)
            if amount_to_pay > 0:
                settlements.append(
                    (debtors[i][1], creditors[j][1], amount_to_pay / 100.0)
                )

            debtors[i][0] -= amount_to_pay
            creditors[j][0] -= amount_to_pay

            if debtors[i][0] == 0:
                i += 1
            if creditors[j][0] == 0:
                j += 1

        return settlements
